function LiveMarketStrip(){const [prices,setPrices]=useState(null),[updated,setUpdated]=useState(null),[error,setError]=useState(false);React.useEffect(()=>{let active=true;const load=async()=>{try{const response=await fetch('https://api.kraken.com/0/public/Ticker?pair=XBTUSD,ETHUSD,USDTUSD,USDCUSD');if(!response.ok)throw Error('Market request failed');const payload=await response.json();if(payload.error?.length)throw Error(payload.error.join(', '));const result=payload.result||{},aliases={BTC:['XXBTZUSD','XBTUSD'],ETH:['XETHZUSD','ETHUSD'],USDT:['USDTZUSD','USDTUSD'],USDC:['USDCUSD']},next={};for(const [symbol,keys] of Object.entries(aliases)){const key=keys.find(k=>result[k]);if(key){const ticker=result[key];next[symbol]={price:Number(ticker.c?.[0]),open:Number(ticker.o)}}}if(!Object.keys(next).length)throw Error('No market pairs returned');if(active){setPrices(next);setUpdated(new Date());setError(false)}}catch{if(active)setError(true)}};load();const timer=setInterval(load,60000);return()=>{active=false;clearInterval(timer)}},[]);return <section className="live-market-strip" aria-label="Live crypto market prices"><div className="market-strip-title"><span className="market-live-indicator"/><div><b>Market</b><small>{error?'Price feed unavailable':updated?`Live Â· updated ${updated.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`:'Loading live prices'}</small></div></div>{assets.map(a=><div className="market-quote" key={a.id}><AssetIcon asset={a.id} size={25}/><span><b>{a.id}/USD</b><small>{prices?.[a.id]?usd(prices[a.id].price):'â€”'}</small></span></div>)}<span className="market-source">Kraken spot Â· indicative</span></section>}
